 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]

    # Sparse 7s are the heads of short rays, and their partner color 1 bars
    # are the limits. Extend the 7 horizontally from each marker to the nearest
    # opposite edge rail; recolor the marker itself to 4.
    freq = {}
    for row in grid:
        for v in row:
            if v != bg:
                freq[v] = freq.get(v, 0) + 1
