             if grid[r][c] not in (bg, rail)]
    for r,c in marks:
        marker_color = grid[r][c]
        out[r][c] = 4
        # Continue marker color to the edge, bounded by the nearest rail pixel.
        # For markers beside a full-height rail, extend along that row away from it.
        left_rail = grid[r][0] == rail
        right_rail = grid[r][w-1] == rail
        if right_rail and not left_rail:
            direction = -1
        elif left_rail and not right_rail:
            direction = 1
        else:
            direction = 1 if c < w//2 else -1
        cc = c + direction
        while 0 <= cc < w:
            if grid[r][cc] == rail:
