            if v != bg:
                freq[v] = freq.get(v, 0) + 1
    guide = max(freq, key=freq.get)
    marks = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != guide]
    # Guide marks extend as guide-colored strips toward the nearest parallel
    # rail. Their own cells become 4. A strip's thickness is the mark's local
    # cluster thickness (1 in these examples).
    for r, c in marks:
        out[r][c] = 4
        # Rays run along the row toward the nearest guide pixel/boundary guide.
        left_dist = next((c-x for x in range(c-1, -1, -1) if grid[r][x] == guide), None)
        right_dist = next((x-c for x in range(c+1, w) if grid[r][x] == guide), None)
        if left_dist is not None and (right_dist is None or left_dist < right_dist):
            step = -1
        elif right_dist is not None:
            step = 1
        else:
            # when the guide runs in another direction, use nearest boundary line
            step = 0
        x = c + step
        while step and 0 <= x < w and grid[r][x] != guide:
            if grid[r][x] == bg:
                out[r][x] = guide
            x += step
    return out
