 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    out = [row[:] for row in grid]

    # Dominant non-background color is the rail; sparse colors are seeds.
    counts = {}
    for row in grid:
        for value in row:
            if value != background:
                counts[value] = counts.get(value, 0) + 1
    if not counts:
        return out
    rail = max(counts, key=counts.get)
    seeds = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (background, rail)]

    # Marks become 4. Each mark's shape is the rectangle extending from the
    # mark toward the nearest long boundary rail, with thickness set by nearby
    # marked points on the perpendicular axis.
    for r, c in seeds:
        out[r][c] = 4

    # Gather contiguous boundary runs of the rail color.
    boundary_runs = []
    for side in ('top', 'bottom', 'left', 'right'):
        coords = ([(0, c) for c in range(w)] if side == 'top' else
                  [(h-1, c) for c in range(w)] if side == 'bottom' else
                  [(r, 0) for r in range(h)] if side == 'left' else
                  [(r, w-1) for r in range(h)])
        i = 0
        while i < len(coords):
            r, c = coords[i]
            if grid[r][c] != rail:
                i += 1
                continue
            run = []
            while i < len(coords) and grid[coords[i][0]][coords[i][1]] == rail:
                run.append(coords[i]); i += 1
            if len(run) >= 2:
                boundary_runs.append((side, run))

    # Each seed is associated with the nearest run in a cardinal direction.
    # Extend a rail-colored strip to that run, spanning the local 3-cell band.
    for r, c in seeds:
        options = []
        for side, dr, dc in (("right", 0, 1), ("left", 0, -1),
                             ("bottom", 1, 0), ("top", -1, 0)):
            rr, cc = r + dr, c + dc
            distance = 1
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                rr += dr; cc += dc; distance += 1
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == rail:
                options.append((distance, dr, dc))
        if not options:
            continue
        _, dr, dc = min(options)
        for offset in (-1, 0, 1):
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != rail:
                sr, sc = (rr, cc + offset) if dr else (rr + offset, cc)
                if 0 <= sr < h and 0 <= sc < w and grid[sr][sc] == background:
                    out[sr][sc] = rail
                rr += dr; cc += dc
    return out
